#define r34(p) fract(30. * sin(p.xyzx + p.xyzx) * sin(p.yzxx))
#define Q(z) P((z), .0, 0., .0, 9., 0.)
#define P(z, a, b, c, d, e) vec3(sin(z * a) * b, cos(z * c) * d - e, z)
void mainImage(out vec4 O, vec2 u){

    vec3  p, r = iResolution, C;       
    float s, t = iTime * -0.22;

    float i = 0.0, a = 0.0;

    O *= 0.0; 
    float colorRangeBottom = 1.0 + 2.1 * sin(t) ; 
    float colorRangeMid = 7.0 + 4.0 * sin(t*2.0) ;   
    float rotationSpeed = sin(t) * 0.2 / 1.0 ; 
    float distanceMax = 2e2 + (sin(t) * 2e2) + 50.0 ; 

    while(i++ < distanceMax){
        s = a + t;

        p = acos(cos(
              vec3((u + u - r.xy) / r.y * a / (10.)
                     * mat2(cos(vec4(0, 11, 33, 0) + rotationSpeed))
                     + vec2(  
                         cos(t * .001) - cos(s * .001),
                         sin(t * .001) - sin(s * .001)
                   ) * -cos(t * .2) / 2., s
              )

        ));


        int j ;
        while(j++ < 2) 
               p= r34(p).xyz;

        p = abs(2.0 * p),

        p = p.x < p.y ? p.zxy : p.zyx,
        p -= vec3(3, 1, 2);


        C = .1 * cos(s * 3.14 / 1. + vec3(colorRangeBottom, colorRangeMid, 13));



        a += s = abs(length(p.xz) / 38. - .054) + 2e-5;

        O.rgb += C * C / exp(i * i / 28. * s);
    }

    O.a = O.r + sin(t) * 0.3;
}

